const textFiles = {
  "src/hooks/useScrollLock.ts": "import { useEffect } from 'react';\n\nlet activeLockCount = 0;\nlet originalScrollY = 0;\nlet originalBodyStyles: {\n  position: string;\n  top: string;\n  left: string;\n  right: string;\n  width: string;\n  overflow: string;\n  touchAction: string;\n} | null = null;\nlet originalHtmlOverflow = '';\n\nexport function useScrollLock(isLocked: boolean = true) {\n  useEffect(() => {\n    if (!isLocked) return;\n\n    if (activeLockCount === 0) {\n      originalScrollY = window.scrollY || window.pageYOffset || document.documentElement.scrollTop || 0;\n      const body = document.body;\n      const html = document.documentElement;\n\n      originalBodyStyles = {\n        position: body.style.position,\n        top: body.style.top,\n        left: body.style.left,\n        right: body.style.right,\n        width: body.style.width,\n        overflow: body.style.overflow,\n        touchAction: body.style.touchAction,\n      };\n      originalHtmlOverflow = html.style.overflow;\n\n      body.style.position = 'fixed';\n      body.style.top = `-${originalScrollY}px`;\n      body.style.left = '0';\n      body.style.right = '0';\n      body.style.width = '100%';\n      body.style.overflow = 'hidden';\n      body.style.touchAction = 'none';\n\n      html.style.overflow = 'hidden';\n    }\n\n    activeLockCount++;\n\n    return () => {\n      activeLockCount--;\n      if (activeLockCount <= 0) {\n        activeLockCount = 0;\n        const body = document.body;\n        const html = document.documentElement;\n\n        if (originalBodyStyles) {\n          body.style.position = originalBodyStyles.position;\n          body.style.top = originalBodyStyles.top;\n          body.style.left = originalBodyStyles.left;\n          body.style.right = originalBodyStyles.right;\n          body.style.width = originalBodyStyles.width;\n          body.style.overflow = originalBodyStyles.overflow;\n          body.style.touchAction = originalBodyStyles.touchAction;\n          originalBodyStyles = null;\n        } else {\n          body.style.position = '';\n          body.style.top = '';\n          body.style.left = '';\n          body.style.right = '';\n          body.style.width = '';\n          body.style.overflow = '';\n          body.style.touchAction = '';\n        }\n\n        html.style.overflow = originalHtmlOverflow;\n        window.scrollTo(0, originalScrollY);\n      }\n    };\n  }, [isLocked]);\n}\n",
  "src/components/RetroBootScreen.tsx": "import React, { useState, useEffect, useRef } from 'react';\nimport { Shield, CheckCircle2, ChevronRight, FolderOpen, Search } from 'lucide-react';\n\ninterface RetroBootScreenProps {\n  onComplete: () => void;\n}\n\nexport const RetroBootScreen: React.FC<RetroBootScreenProps> = ({ onComplete }) => {\n  const [progress, setProgress] = useState(0);\n  const [logs, setLogs] = useState<string[]>([\n    'POLÍCIA CIVIL SP · DELEGACIA DE HOMICÍDIOS E INVESTIGAÇÕES GERAIS (1995)',\n    'ABRINDO INQUÉRITO POLICIAL 042/95 · RANCHO ESPERANÇA...',\n  ]);\n  const [isReady, setIsReady] = useState(false);\n  const hasFinishedRef = useRef(false);\n\n  useEffect(() => {\n    const assetsToLoad: string[] = [\n      ...Array.from({ length: 16 }, (_, i) => `/assets/detetive/frame_${String(i).padStart(2, '0')}.png`),\n      ...Array.from({ length: 8 }, (_, i) => `/assets/detetive_derrota/frame_${String(i).padStart(2, '0')}.png`),\n      '/assets/aistudio/Detetive_Pixelado_no_Ref_gio_Aconchegante_674d8c38.png',\n      '/assets/vhs_strip.png',\n      '/assets/claquete_strip.png',\n      '/assets/revolver_strip.png',\n      '/assets/ampulheta_strip.png',\n      '/assets/lupa_strip.png',\n      '/assets/aistudio/AG_FC_44a91d2b.jpg',\n      '/assets/aistudio/1_994dbf90.jpg',\n      '/assets/aistudio/2_d8fcfc06.jpg',\n      '/assets/aistudio/3_259d20ba.jpg',\n      '/assets/aistudio/4_88dd4e00.jpg',\n      '/assets/aistudio/5_666b334d.jpg',\n      '/assets/aistudio/6_5c870541.jpg',\n      '/assets/aistudio/7_aa3e89d6.jpg',\n      '/assets/aistudio/8_6ce7ced0.jpg',\n      '/assets/aistudio/9_467f2335.jpg',\n      '/assets/aistudio/10_df7bff44.jpg',\n      '/Tratadas/MARCOS 3.jpg',\n      '/Tratadas/MONICA 3.jpg',\n    ];\n\n    let loadedCount = 0;\n    const totalAssets = assetsToLoad.length + 1;\n\n    const updateProgress = (itemName: string) => {\n      loadedCount++;\n      const currentPct = Math.min(100, Math.floor((loadedCount / totalAssets) * 100));\n      setProgress(currentPct);\n\n      if (currentPct >= 20 && currentPct < 45) {\n        setLogs((prev) =>\n          prev.includes('[OK] LAUDO GRAFOTÉCNICO E DOCUMENTOS DATILOGRAFADOS REUNIDOS')\n            ? prev\n            : [...prev, '[OK] LAUDO GRAFOTÉCNICO E DOCUMENTOS DATILOGRAFADOS REUNIDOS']\n        );\n      } else if (currentPct >= 45 && currentPct < 75) {\n        setLogs((prev) =>\n          prev.includes('[OK] DOSSIÊ DE SUSPEITOS E DEPOIMENTOS DA EQUIPE REUNIDOS')\n            ? prev\n            : [...prev, '[OK] DOSSIÊ DE SUSPEITOS E DEPOIMENTOS DA EQUIPE REUNIDOS']\n        );\n      } else if (currentPct >= 75 && currentPct < 95) {\n        setLogs((prev) =>\n          prev.includes('[OK] REGISTROS VISUAIS DA CENA E PERFIL DO INVESTIGADOR PREPARADOS')\n            ? prev\n            : [...prev, '[OK] REGISTROS VISUAIS DA CENA E PERFIL DO INVESTIGADOR PREPARADOS']\n        );\n      } else if (currentPct >= 95) {\n        setLogs((prev) =>\n          prev.includes('[OK] INQUÉRITO COMPLETO · 21 EVIDÊNCIAS PRONTAS PARA ANÁLISE')\n            ? prev\n            : [...prev, '[OK] INQUÉRITO COMPLETO · 21 EVIDÊNCIAS PRONTAS PARA ANÁLISE']\n        );\n      }\n    };\n\n    const loadFont = async () => {\n      try {\n        if (typeof document !== 'undefined' && document.fonts) {\n          await document.fonts.load('1em \"Brunson Rough\"');\n          await document.fonts.ready;\n        }\n      } catch (err) {\n        console.warn('Font preload check bypassed', err);\n      } finally {\n        updateProgress('Brunson Font');\n      }\n    };\n\n    loadFont();\n\n    assetsToLoad.forEach((src) => {\n      const img = new Image();\n      img.onload = () => updateProgress(src);\n      img.onerror = () => updateProgress(src);\n      img.src = src;\n    });\n\n    const timeout = setTimeout(() => {\n      setProgress(100);\n      setIsReady(true);\n    }, 4500);\n\n    return () => clearTimeout(timeout);\n  }, []);\n\n  useEffect(() => {\n    if (progress >= 100 && !isReady) {\n      setIsReady(true);\n      const timer = setTimeout(() => {\n        handleProceed();\n      }, 500);\n      return () => clearTimeout(timer);\n    }\n  }, [progress, isReady]);\n\n  const handleProceed = () => {\n    if (hasFinishedRef.current) return;\n    hasFinishedRef.current = true;\n    onComplete();\n  };\n\n  const totalBlocks = 24;\n  const filledBlocks = Math.round((progress / 100) * totalBlocks);\n  const emptyBlocks = Math.max(0, totalBlocks - filledBlocks);\n  const barString = '█'.repeat(filledBlocks) + '░'.repeat(emptyBlocks);\n\n  return (\n    <div className=\"fixed inset-0 z-[9999] bg-[#07080a] text-[#F2EAE0] flex flex-col items-center justify-center p-4 select-none font-mono-retro\">\n      <div\n        className=\"absolute inset-0 pointer-events-none opacity-25\"\n        style={{\n          backgroundImage:\n            'repeating-linear-gradient(0deg, rgba(0,0,0,0.6) 0px, rgba(0,0,0,0.6) 1px, transparent 1px, transparent 2px)',\n          backgroundSize: '100% 2px',\n        }}\n      />\n\n      <div className=\"relative w-full max-w-[620px] bg-[#0c0e12] border-2 border-[#262830] rounded-xl shadow-[0_0_60px_rgba(0,0,0,0.95)] overflow-hidden flex flex-col\">\n        <div className=\"bg-[#14161d] border-b border-[#242730] px-4 py-2.5 flex items-center justify-between\">\n          <div className=\"flex items-center gap-2\">\n            <Shield className=\"w-4 h-4 text-[#7DD5D8]\" />\n            <span className=\"text-[11px] sm:text-[12px] font-bold text-[#7DD5D8] tracking-[0.14em]\">\n              SSP-SP · POLÍCIA CIVIL DE SÃO PAULO (1995)\n            </span>\n          </div>\n          <div className=\"flex items-center gap-1.5 text-[10px] text-[#9A9590]\">\n            <FolderOpen className=\"w-3.5 h-3.5 text-[#E6C687]\" />\n            <span className=\"text-[#E6C687]\">PASTA DO INQUÉRITO 1/1</span>\n          </div>\n        </div>\n\n        <div className=\"p-4 sm:p-6 flex flex-col gap-4 text-xs sm:text-[13px] leading-relaxed\">\n          <div className=\"border-b border-[#1c1e26] pb-3 text-[#9A9590] flex flex-col gap-0.5\">\n            <div className=\"text-[#F2EAE0] font-bold tracking-wider\">\n              INQUÉRITO POLICIAL #1995-1013 · CASO ALICE GUY [RANCHO ESPERANÇA]\n            </div>\n            <div className=\"text-[11px] text-[#7DD5D8]/80\">\n              DOSSIÊ CONFIDENCIAL: RECONSTITUIÇÃO DOS FATOS, FITAS E SUSPEITOS\n            </div>\n          </div>\n\n          <div className=\"bg-[#050608] border border-[#1b1c24] rounded-lg p-3 min-h-[140px] max-h-[160px] overflow-hidden flex flex-col justify-end text-[11px] sm:text-[12px] text-[#A6A29A]\">\n            {logs.slice(-5).map((log, index) => (\n              <div\n                key={index}\n                className={`py-0.5 flex items-center gap-1.5 ${\n                  log.startsWith('[OK]') ? 'text-[#4CAF50] font-bold' : 'text-[#7DD5D8]'\n                }`}\n              >\n                {log.startsWith('[OK]') ? (\n                  <CheckCircle2 className=\"w-3.5 h-3.5 flex-shrink-0 text-[#4CAF50]\" />\n                ) : (\n                  <ChevronRight className=\"w-3.5 h-3.5 flex-shrink-0 text-[#7DD5D8]\" />\n                )}\n                <span className=\"truncate\">{log}</span>\n              </div>\n            ))}\n            <div className=\"flex items-center gap-1.5 text-[#7DD5D8] pt-1\">\n              <span>&gt; ORGANIZANDO ARQUIVOS DA INVESTIGAÇÃO...</span>\n              <span className=\"inline-block w-2 h-3.5 bg-[#7DD5D8] animate-pulse\" />\n            </div>\n          </div>\n\n          <div className=\"flex flex-col gap-2 pt-1\">\n            <div className=\"flex items-center justify-between text-[11px] text-[#9A9590]\">\n              <span className=\"tracking-wider uppercase\">PREPARAÇÃO DO DOSSIÊ DO CASO:</span>\n              <span className=\"font-bold text-[#7DD5D8]\">{progress}%</span>\n            </div>\n\n            <div className=\"bg-[#050608] border border-[#262830] rounded-lg p-2.5 text-center font-mono text-sm tracking-[2px] text-[#7DD5D8] select-none overflow-x-hidden\">\n              [{barString}]\n            </div>\n          </div>\n\n          <div className=\"pt-2 flex justify-end\">\n            <button\n              type=\"button\"\n              onClick={handleProceed}\n              className={`px-4 py-2 rounded border text-xs font-bold tracking-wider uppercase transition-all duration-200 flex items-center gap-2 ${\n                isReady\n                  ? 'bg-[#7DD5D8] text-black border-[#7DD5D8] shadow-[0_0_15px_rgba(125,213,216,0.4)] animate-pulse cursor-pointer'\n                  : 'bg-[#15171e] text-[#6b7280] border-[#22242c] hover:text-[#9A9590] cursor-pointer'\n              }`}\n            >\n              <Search className=\"w-3.5 h-3.5\" />\n              <span>{isReady ? 'INICIAR INVESTIGAÇÃO' : 'ACESSAR INQUÉRITO'}</span>\n              <span className=\"font-mono text-[10px] opacity-75\">[ENTER ↵]</span>\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n};\n",
  "src/App.tsx": "import React, { useState, useEffect } from 'react';\nimport {\n  AllAnswers,\n  CharacterVerificationResult,\n  FieldKey,\n  FinalVerificationResult,\n} from './types';\nimport {\n  ENDINGS,\n  EV,\n  GAB,\n  getOptionLabel,\n  HINTS,\n  match,\n  MOCK_FICHAS,\n  MOCK_FICHAS_WRONG,\n  MOCK_SEQ,\n  MOCK_SEQ_WRONG,\n  PERS,\n  shuffle,\n} from './data/evidence';\nimport { Header } from './components/Header';\nimport { Navigation, TabType } from './components/Navigation';\nimport { HomeScreen } from './components/HomeScreen';\nimport { FitasTab } from './components/FitasTab';\nimport { SequenciaTab } from './components/SequenciaTab';\nimport { FichasTab } from './components/FichasTab';\nimport { ExamSheet } from './components/ExamSheet';\nimport { ResultModal } from './components/ResultModal';\nimport { RetroSheetModal } from './components/RetroSheetModal';\nimport { FlamingSkullEffect, TimelineAnimationType } from './components/FlamingSkullEffect';\nimport { DetectiveBriefingModal } from './components/DetectiveBriefingModal';\nimport { DetectiveDefeatModal } from './components/DetectiveDefeatModal';\nimport { DetectiveVictoryModal } from './components/DetectiveVictoryModal';\nimport { RetroBootScreen } from './components/RetroBootScreen';\n\nexport const App: React.FC = () => {\n  // Game state\n  const [isBooting, setIsBooting] = useState(true);\n  const [deck, setDeck] = useState(() => shuffle(EV));\n  const [vistas, setVistas] = useState<Set<string>>(() => new Set());\n  const [sequence, setSequence] = useState<string[]>([]);\n  const [examIdx, setExamIdx] = useState<number | null>(null);\n  const [activeTab, setActiveTab] = useState<TabType>('fitas');\n  const [answers, setAnswers] = useState<AllAnswers>({});\n  const [fieldStatuses, setFieldStatuses] = useState<\n    Record<string, Record<FieldKey, 'ok' | 'err' | 'amb' | undefined>>\n  >({});\n  const [verificationResult, setVerificationResult] = useState<FinalVerificationResult | null>(null);\n  const [isHomeOpen, setIsHomeOpen] = useState(true);\n  const [isBriefingOpen, setIsBriefingOpen] = useState(false);\n  const [isDefeatOpen, setIsDefeatOpen] = useState(false);\n  const [isVictoryOpen, setIsVictoryOpen] = useState(false);\n  const [isRetroSheetOpen, setIsRetroSheetOpen] = useState(false);\n  const [timelineAnimTrigger, setTimelineAnimTrigger] = useState(0);\n  const [timelineAnimType, setTimelineAnimType] = useState<TimelineAnimationType>('vhs');\n\n  // Counters\n  const vistasCount = vistas.size;\n  const unseenCount = 21 - vistasCount;\n  let camposCount = 0;\n  PERS.forEach(p => {\n    const pAns = answers[p.id];\n    if (pAns) {\n      if (pAns.ordem) camposCount++;\n      if (pAns.local) camposCount++;\n      if (pAns.quando) camposCount++;\n      if (pAns.como) camposCount++;\n    }\n  });\n\n  const hasProgress = () => {\n    if (vistas.size > 0 || sequence.length > 0) return true;\n    return Object.values(answers).some(pAns =>\n      Object.values(pAns).some(v => Boolean(v))\n    );\n  };\n\n  const handleStart = () => {\n    setIsHomeOpen(false);\n    if (!hasProgress()) {\n      setIsBriefingOpen(true);\n    }\n  };\n\n  const handleFinishBriefing = () => {\n    setIsBriefingOpen(false);\n    setIsHomeOpen(false);\n  };\n\n  const handleGoHome = () => {\n    if (typeof window !== 'undefined' && window.speechSynthesis) {\n      window.speechSynthesis.cancel();\n    }\n    setExamIdx(null);\n    setVerificationResult(null);\n    setIsDefeatOpen(false);\n    setIsVictoryOpen(false);\n    setIsHomeOpen(true);\n  };\n\n  const handleOpenExam = (idx: number) => {\n    setExamIdx(idx);\n    const ev = deck[idx];\n    if (ev) {\n      setVistas(prev => {\n        const next = new Set(prev);\n        next.add(ev.id);\n        return next;\n      });\n    }\n  };\n\n  const handleOpenByEvId = (evId: string) => {\n    const idx = deck.findIndex(e => e.id === evId);\n    if (idx !== -1) {\n      handleOpenExam(idx);\n    }\n  };\n\n  const handleCloseExam = () => {\n    setExamIdx(null);\n  };\n\n  const handleAddToSeq = (evId: string) => {\n    setSequence(prev => {\n      if (prev.includes(evId)) return prev;\n      const animCycle: TimelineAnimationType[] = ['vhs', 'claquete', 'revolver', 'ampulheta', 'lupa'];\n      const nextType = animCycle[prev.length % animCycle.length];\n      setTimelineAnimType(nextType);\n      setTimelineAnimTrigger(t => t + 1);\n      return [...prev, evId];\n    });\n  };\n\n  const handleRemoveFromSeq = (evId: string) => {\n    setSequence(prev => prev.filter(id => id !== evId));\n  };\n\n  const handleMoveSeq = (evId: string, dir: number) => {\n    setSequence(prev => {\n      const idx = prev.indexOf(evId);\n      if (idx === -1) return prev;\n      const targetIdx = idx + dir;\n      if (targetIdx < 0 || targetIdx >= prev.length) return prev;\n      const next = [...prev];\n      [next[idx], next[targetIdx]] = [next[targetIdx], next[idx]];\n      return next;\n    });\n  };\n\n  const handleClearSeq = () => {\n    setSequence([]);\n  };\n\n  const handleAnswerChange = (pid: string, field: FieldKey, val: string) => {\n    setAnswers(prev => ({\n      ...prev,\n      [pid]: {\n        ...(prev[pid] || {}),\n        [field]: val,\n      },\n    }));\n    setFieldStatuses(prev => ({\n      ...prev,\n      [pid]: {\n        ...(prev[pid] || {}),\n        [field]: undefined,\n      },\n    }));\n  };\n\n  const calculateSeqScore = () => {\n    if (sequence.length === 0) return 0;\n    let hits = 0;\n    for (let i = 0; i < Math.min(sequence.length, MOCK_SEQ.length); i++) {\n      if (sequence[i] === MOCK_SEQ[i]) hits++;\n    }\n    return hits / MOCK_SEQ.length;\n  };\n\n  const handleConclude = () => {\n    let tot = 0;\n    let cor = 0;\n    const dets: CharacterVerificationResult[] = [];\n    const newStatuses: Record<string, Record<FieldKey, 'ok' | 'err' | 'amb'>> = {};\n\n    PERS.forEach(p => {\n      const gab = GAB[p.id];\n      newStatuses[p.id] = { ordem: 'err', local: 'err', quando: 'err', como: 'err' };\n\n      const campos = (['ordem', 'local', 'quando', 'como'] as FieldKey[]).map(f => {\n        const val = answers[p.id]?.[f] || '';\n        let ok: boolean;\n        let cls: 'ok' | 'err' | 'amb';\n\n        if (gab.especial && f === 'ordem') {\n          ok = true;\n          cls = 'amb';\n          tot++;\n          cor++;\n        } else {\n          ok = match(val, gab[f] || []);\n          cls = ok ? 'ok' : 'err';\n          tot++;\n          if (ok) cor++;\n        }\n\n        newStatuses[p.id][f] = cls;\n\n        return {\n          label: { ordem: 'Ordem', local: 'Local', quando: 'Horário', como: 'Causa' }[f],\n          val: getOptionLabel(f, val),\n          ok,\n          cls,\n          hint: HINTS[p.id]?.[f] || '',\n        };\n      });\n\n      dets.push({ p, campos, especial: gab.especial });\n    });\n\n    setFieldStatuses(newStatuses);\n\n    const pct = Math.round((cor / tot) * 100);\n    const seqFraction = calculateSeqScore();\n    const seqPct = Math.round(seqFraction * 100);\n    const seqHits = Math.round(seqFraction * MOCK_SEQ.length);\n\n    let endingKey: 'total' | 'fichas-ok' | 'seq-ok' | 'parcial' | 'inconclusivo';\n    if (pct >= 85) endingKey = 'total';\n    else if (pct >= 50) endingKey = 'parcial';\n    else endingKey = 'inconclusivo';\n\n    const endingObj = ENDINGS[endingKey];\n    const infoText = endingObj.info;\n\n    setVerificationResult({\n      scoreCor: cor,\n      scoreTot: tot,\n      pct,\n      seqPct,\n      seqHits,\n      endingKey,\n      stamp: endingObj.stamp,\n      color: endingObj.color,\n      info: infoText,\n      details: dets,\n    });\n\n    // Show victory or defeat modal depending on result\n    if (endingKey === 'total') {\n      setIsVictoryOpen(true);\n      setIsDefeatOpen(false);\n    } else {\n      setIsVictoryOpen(false);\n      setIsDefeatOpen(true);\n    }\n  };\n\n  const handleReviewFromDefeat = () => {\n    setIsDefeatOpen(false);\n  };\n\n  const handleRestartFromDefeat = () => {\n    setIsDefeatOpen(false);\n    handleRestart();\n  };\n\n  const handleRestart = () => {\n    setDeck(shuffle(EV));\n    setVistas(new Set());\n    setSequence([]);\n    setExamIdx(null);\n    setAnswers({});\n    setFieldStatuses({});\n    setVerificationResult(null);\n    setIsDefeatOpen(false);\n    setIsVictoryOpen(false);\n    setActiveTab('fitas');\n    setTimelineAnimTrigger(0);\n    setIsBriefingOpen(true);\n    setIsHomeOpen(false);\n  };\n\n  const handleMockSuccess = () => {\n    setAnswers(MOCK_FICHAS);\n    setSequence(MOCK_SEQ.filter(id => EV.some(e => e.id === id)));\n  };\n\n  const handleMockError = () => {\n    setAnswers(MOCK_FICHAS_WRONG);\n    setSequence(MOCK_SEQ_WRONG.filter(id => EV.some(e => e.id === id)));\n  };\n\n  const currentExamEv = examIdx !== null ? deck[examIdx] : null;\n\n  if (isBooting) {\n    return <RetroBootScreen onComplete={() => setIsBooting(false)} />;\n  }\n\n  return (\n    <div className=\"min-h-screen bg-[#0D0D0D] text-[#F2EAE0] font-sans selection:bg-[#7DD5D8] selection:text-[#0D0D0D]\">\n      {/* Home Screen Modal */}\n      <HomeScreen\n        isOpen={isHomeOpen}\n        hasProgress={hasProgress()}\n        onStart={handleStart}\n        onRestart={handleRestart}\n      />\n\n      {/* Detective Briefing Modal on Game Start */}\n      <DetectiveBriefingModal\n        isOpen={isBriefingOpen}\n        onClose={handleFinishBriefing}\n      />\n\n      {/* Main App Layout */}\n      {!isHomeOpen && (\n        <>\n          <Header\n            vistasCount={vistasCount}\n            camposCount={camposCount}\n            onGoHome={handleGoHome}\n          />\n\n          <main id=\"content\" className=\"pb-[64px]\">\n            {activeTab === 'fitas' && (\n              <FitasTab\n                deck={deck}\n                vistas={vistas}\n                sequence={sequence}\n                examIdx={examIdx}\n                onOpenExam={handleOpenExam}\n              />\n            )}\n\n            {activeTab === 'seq' && (\n              <SequenciaTab\n                sequence={sequence}\n                currentExamEvId={currentExamEv?.id || null}\n                onOpenByEvId={handleOpenByEvId}\n                onMoveSeq={handleMoveSeq}\n                onRemoveFromSeq={handleRemoveFromSeq}\n                onClearSeq={handleClearSeq}\n              />\n            )}\n\n            {activeTab === 'fichas' && (\n              <FichasTab\n                answers={answers}\n                fieldStatuses={fieldStatuses}\n                onAnswerChange={handleAnswerChange}\n                onConclude={handleConclude}\n              />\n            )}\n          </main>\n\n          {/* Navigation */}\n          <Navigation\n            activeTab={activeTab}\n            onTabChange={setActiveTab}\n            unseenCount={unseenCount}\n            sequenceCount={sequence.length}\n            camposCount={camposCount}\n          />\n\n          {/* Bottom Sheet Exam */}\n          <ExamSheet\n            evidence={currentExamEv}\n            sequence={sequence}\n            isOpen={examIdx !== null}\n            onClose={handleCloseExam}\n            onAddToSeq={handleAddToSeq}\n            onMoveSeq={handleMoveSeq}\n            onRemoveFromSeq={handleRemoveFromSeq}\n            onOpenRetroSheet={() => setIsRetroSheetOpen(true)}\n          />\n\n          {/* Detective Defeat Modal on Failed Investigation */}\n          <DetectiveDefeatModal\n            isOpen={isDefeatOpen}\n            onReview={handleReviewFromDefeat}\n            onRestart={handleRestartFromDefeat}\n          />\n\n          {/* Detective Victory Modal on Solved Investigation */}\n          <DetectiveVictoryModal\n            isOpen={isVictoryOpen}\n            onReview={() => setIsVictoryOpen(false)}\n            onRestart={handleRestart}\n          />\n\n          {/* Result Modal */}\n          <ResultModal\n            result={verificationResult}\n            isOpen={verificationResult !== null && !isDefeatOpen && !isVictoryOpen}\n            onClose={() => {\n              setVerificationResult(null);\n              setActiveTab('fichas');\n            }}\n            onRestart={handleRestart}\n            onGoHome={handleGoHome}\n          />\n\n          {/* RetroSheet-95 Spreadsheet Modal */}\n          <RetroSheetModal\n            isOpen={isRetroSheetOpen}\n            onClose={() => setIsRetroSheetOpen(false)}\n          />\n\n          {/* Alternating Timeline Addition Effect (1st Skull, 2nd VHS, etc.) */}\n          <FlamingSkullEffect\n            triggerSignal={timelineAnimTrigger}\n            animationType={timelineAnimType}\n          />\n\n          {/* Hidden pre-warm container for mobile GPU texture cache */}\n          <div style={{ position: 'absolute', width: 1, height: 1, overflow: 'hidden', opacity: 0, pointerEvents: 'none' }} aria-hidden=\"true\">\n            <div className=\"sprite-vhs\" />\n            <div className=\"sprite-claquete\" />\n            <div className=\"sprite-revolver\" />\n            <div className=\"sprite-ampulheta\" />\n            <div className=\"sprite-lupa\" />\n          </div>\n\n          {/* Dev / Test Mock Buttons */}\n          <aside className=\"fixed bottom-[calc(var(--nav-h)+10px)] right-[10px] z-[140] flex gap-[5px]\">\n            <button\n              type=\"button\"\n              id=\"btn-mock\"\n              onClick={handleMockSuccess}\n              title=\"Preencher com respostas e sequência corretas\"\n              className=\"bg-[#222222] border border-[#303030] text-[#9A9590] font-mono-retro text-[9px] px-[8px] py-[5px] cursor-pointer rounded-[4px] hover:border-[#9A9590] hover:text-[#F2EAE0] transition-all tracking-[0.06em]\"\n            >\n              Mock ⚡\n            </button>\n            <button\n              type=\"button\"\n              id=\"btn-mock-err\"\n              onClick={handleMockError}\n              title=\"Preencher com respostas e sequência incorretas\"\n              className=\"bg-[#3A1010] border border-[#D94040] text-[#D94040] font-mono-retro text-[9px] px-[8px] py-[5px] cursor-pointer rounded-[4px] hover:border-[#ff6060] hover:text-[#ff8080] transition-all tracking-[0.06em]\"\n            >\n              Erro ✗\n            </button>\n          </aside>\n        </>\n      )}\n    </div>\n  );\n};\n\nexport default App;\n",
  "src/components/DetectiveBriefingModal.tsx": "import React, { useState, useEffect } from 'react';\nimport { ChevronRight, ChevronLeft, FastForward, Search, ShieldAlert, Sparkles } from 'lucide-react';\nimport { useScrollLock } from '../hooks/useScrollLock';\n\ninterface BriefingSlide {\n  title: string;\n  text: string;\n  frames: number[]; // Index of frames from public/assets/detetive/frame_XX.png\n  badge: string;\n}\n\nconst BRIEFING_SLIDES: BriefingSlide[] = [\n  {\n    badge: 'RELATÓRIO INICIAL',\n    title: 'O Chamado no Rancho Esperança',\n    text: 'Detetive na área. No dia 13 de outubro de 1995, uma equipe de cinema independente desapareceu no isolado Rancho Esperança. A polícia encontrou o local intacto, mas repleto de marcas de sangue e pistas espalhadas.',\n    frames: [0, 1, 2, 3],\n  },\n  {\n    badge: 'EVIDÊNCIAS COLETADAS',\n    title: 'As 21 Fitas e Achados',\n    text: 'Recuperamos 21 evidências e fitas gravadas durante aquela noite. Cada fotografia de cena, documento e áudio gravado contém detalhes valiosos para reconstruir o que realmente aconteceu no rancho.',\n    frames: [4, 5, 6, 7],\n  },\n  {\n    badge: 'DIRETRIZES DA MISSÃO',\n    title: 'Seu Objetivo Investigativo',\n    text: 'Sua missão é dupla: primeiro, ordenar as 21 fitas na Linha do Tempo cronológica. Segundo, preencher as fichas dos 7 personagens determinando a ordem da morte, local, horário e causa precisa.',\n    frames: [8, 9, 10, 11],\n  },\n  {\n    badge: 'ALERTA DO DETETIVE',\n    title: 'A Busca pela Verdade',\n    text: 'Preste atenção aos detalhes nas fotos e escute atentamente os relatos em áudio do gravador policial. As aparências enganam... Boa sorte, investigador. O caso está em suas mãos.',\n    frames: [12, 13, 14, 15],\n  },\n];\n\ninterface DetectiveBriefingModalProps {\n  isOpen: boolean;\n  onClose: () => void;\n}\n\nexport const DetectiveBriefingModal: React.FC<DetectiveBriefingModalProps> = ({\n  isOpen,\n  onClose,\n}) => {\n  const [currentSlideIndex, setCurrentSlideIndex] = useState(0);\n  const [currentFrameInSlide, setCurrentFrameInSlide] = useState(0);\n\n  // Rigid scroll lock on all mobile & desktop viewports\n  useScrollLock(isOpen);\n\n  // Always reset to the first card when the report is opened\n  useEffect(() => {\n    if (isOpen) {\n      setCurrentSlideIndex(0);\n      setCurrentFrameInSlide(0);\n    }\n  }, [isOpen]);\n\n  const slide = BRIEFING_SLIDES[currentSlideIndex];\n\n  // Animate detective frame transitions (~450ms per frame)\n  useEffect(() => {\n    if (!isOpen) return;\n\n    setCurrentFrameInSlide(0);\n    const interval = setInterval(() => {\n      setCurrentFrameInSlide((prev) => (prev + 1) % slide.frames.length);\n    }, 450);\n\n    return () => {\n      clearInterval(interval);\n    };\n  }, [currentSlideIndex, isOpen, slide.frames.length]);\n\n  if (!isOpen) return null;\n\n  const activeFrameIdx = slide.frames[currentFrameInSlide];\n\n  const isFirstSlide = currentSlideIndex === 0;\n  const isLastSlide = currentSlideIndex === BRIEFING_SLIDES.length - 1;\n\n  const handleNext = () => {\n    if (isLastSlide) {\n      onClose();\n    } else {\n      setCurrentSlideIndex((prev) => prev + 1);\n    }\n  };\n\n  const handlePrev = () => {\n    if (!isFirstSlide) {\n      setCurrentSlideIndex((prev) => prev - 1);\n    }\n  };\n\n  return (\n    <div\n      className=\"fixed inset-0 z-[2000] bg-black/85 backdrop-blur-md flex items-center justify-center p-3 sm:p-5 overflow-y-auto overscroll-contain touch-pan-y animate-fadeIn\"\n      role=\"dialog\"\n      aria-modal=\"true\"\n      aria-label=\"Relatório Inicial do Detetive\"\n      onTouchMove={(e) => {\n        if (e.target === e.currentTarget) {\n          e.preventDefault();\n        }\n      }}\n    >\n      <div className=\"w-full max-w-[620px] bg-[#16171b] border-2 border-[#2d3038] rounded-[16px] shadow-[0_12px_50px_rgba(0,0,0,0.85)] overflow-hidden flex flex-col my-auto relative\">\n        \n        {/* Header Bar */}\n        <div className=\"bg-[#0f1013] border-b border-[#282b33] p-[12px_16px] flex items-center justify-between gap-3\">\n          <div className=\"flex items-center gap-2 min-w-0\">\n            <ShieldAlert className=\"w-4 h-4 text-[#d94040] flex-shrink-0\" />\n            <span className=\"font-mono-retro text-[11px] sm:text-[12px] tracking-[0.14em] uppercase text-[#F2EAE0] font-bold truncate\">\n              RELATÓRIO INICIAL · CASO #1995-1013\n            </span>\n          </div>\n\n          <button\n            type=\"button\"\n            onClick={onClose}\n            title=\"Pular introdução e ir direto ao jogo\"\n            aria-label=\"Pular introdução\"\n            className=\"flex items-center gap-1.5 px-3 py-1.5 rounded-[6px] bg-[#22252e] hover:bg-[#2e3340] border border-[#383e4e] font-mono-retro text-[10px] sm:text-[11px] uppercase tracking-[0.08em] text-[#9A9590] hover:text-[#F2EAE0] cursor-pointer transition-colors flex-shrink-0\"\n          >\n            <span>Pular Introdução</span>\n            <FastForward className=\"w-3.5 h-3.5 text-[#d94040]\" />\n          </button>\n        </div>\n\n        {/* Modal Main Area */}\n        <div className=\"p-4 sm:p-6 flex flex-col gap-4\">\n          \n          {/* Slide Progress Pills */}\n          <div className=\"flex items-center justify-between gap-2\">\n            <span className=\"font-mono-retro text-[10px] sm:text-[11px] uppercase tracking-[0.12em] text-[#7DD5D8] font-semibold bg-[#0f1115] px-2.5 py-1 rounded-[4px] border border-[#222630]\">\n              {slide.badge}\n            </span>\n            <div className=\"flex items-center gap-1.5\">\n              {BRIEFING_SLIDES.map((_, idx) => (\n                <div\n                  key={idx}\n                  className={`h-1.5 rounded-full transition-all duration-300 ${\n                    idx === currentSlideIndex\n                      ? 'w-6 bg-[#d94040] shadow-[0_0_8px_rgba(217,64,64,0.6)]'\n                      : idx < currentSlideIndex\n                      ? 'w-2 bg-[#7DD5D8]'\n                      : 'w-2 bg-[#2a2e38]'\n                  }`}\n                />\n              ))}\n              <span className=\"font-mono-retro text-[11px] text-[#9A9590] ml-1.5 font-bold\">\n                {currentSlideIndex + 1}/{BRIEFING_SLIDES.length}\n              </span>\n            </div>\n          </div>\n\n          {/* Speech / Dialogue Box */}\n          <div className=\"bg-[#1e1a16] border-2 border-[#3d3328] rounded-[12px] p-4 sm:p-5 relative shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)]\">\n            <div className=\"font-mono-retro text-[10px] text-[#b39566] tracking-[0.1em] uppercase mb-1 flex items-center gap-1\">\n              <Sparkles className=\"w-3 h-3 text-[#d9ac66]\" />\n              <span>Instruções do Detetive</span>\n            </div>\n            \n            <h3 className=\"font-brunson text-[24px] sm:text-[28px] uppercase tracking-[0.03em] leading-tight text-[#F2EAE0] mb-2\">\n              {slide.title}\n            </h3>\n\n            <p className=\"font-mono-retro text-[13px] sm:text-[14px] text-[#d9c49c] leading-[1.7] italic\">\n              \"{slide.text}\"\n            </p>\n\n            {/* Speech bubble tail pointing down toward detective */}\n            <div className=\"absolute -bottom-3 left-1/2 -translate-x-1/2 w-0 h-0 border-l-[10px] border-l-transparent border-r-[10px] border-r-transparent border-t-[12px] border-t-[#3d3328]\" />\n          </div>\n\n          {/* Detective Pixel Art Character Showcase (Pre-rendered stack, zero blinking) */}\n          <div className=\"relative h-[190px] sm:h-[220px] bg-gradient-to-b from-[#0b0c0e] via-[#12141a] to-[#1a1c24] border border-[#282c38] rounded-[12px] flex items-center justify-center overflow-hidden shadow-inner\">\n            {/* Ambient Background Grid / Light Glow */}\n            <div className=\"absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(217,64,64,0.12)_0%,transparent_70%)] pointer-events-none\" />\n            <div className=\"absolute bottom-0 inset-x-0 h-8 bg-gradient-to-t from-[#16171b] to-transparent pointer-events-none z-20\" />\n\n            {/* Pre-rendered frame stack: All frames remain mounted so transitions are instant with zero blinking */}\n            {Array.from({ length: 16 }, (_, i) => {\n              const isCurrent = i === activeFrameIdx;\n              return (\n                <img\n                  key={i}\n                  src={`/assets/detetive/frame_${String(i).padStart(2, '0')}.png`}\n                  alt=\"Detetive em Pixel Art\"\n                  className={`absolute inset-0 m-auto h-[180px] sm:h-[210px] w-auto object-contain image-rendering-pixelated ${\n                    isCurrent ? 'opacity-100 z-10' : 'opacity-0 pointer-events-none z-0'\n                  }`}\n                  style={{ imageRendering: 'pixelated' }}\n                />\n              );\n            })}\n\n            {/* Subtitle tag */}\n            <div className=\"absolute bottom-2 left-3 z-30 font-mono-retro text-[9px] uppercase tracking-[0.14em] text-[#9A9590] bg-[#0d0e11]/80 px-2 py-0.5 rounded border border-[#22252e]\">\n              DETETIVE RESPONSÁVEL · DEPOIMENTO #{currentSlideIndex + 1}\n            </div>\n          </div>\n\n          {/* Controls Bar */}\n          <div className=\"flex items-center justify-between gap-3 pt-1\">\n            <button\n              type=\"button\"\n              onClick={handlePrev}\n              disabled={isFirstSlide}\n              className=\"h-[44px] px-4 rounded-[8px] bg-[#22252e] border border-[#323746] text-[#F2EAE0] font-mono-retro text-[12px] uppercase tracking-[0.08em] font-bold cursor-pointer hover:bg-[#2c313f] disabled:opacity-30 disabled:cursor-not-allowed transition-all flex items-center gap-1.5\"\n            >\n              <ChevronLeft className=\"w-4 h-4\" />\n              <span>Anterior</span>\n            </button>\n\n            <button\n              type=\"button\"\n              onClick={handleNext}\n              className={`h-[44px] px-5 rounded-[8px] font-mono-retro text-[12px] sm:text-[13px] uppercase tracking-[0.08em] font-bold cursor-pointer transition-all flex items-center gap-2 shadow-[0_4px_12px_rgba(0,0,0,0.4)] ${\n                isLastSlide\n                  ? 'bg-[#d94040] text-white hover:bg-[#c03434] shadow-[0_0_15px_rgba(217,64,64,0.4)]'\n                  : 'bg-[#7DD5D8] text-[#0D0D0D] hover:bg-[#9DE0E3]'\n              }`}\n            >\n              {isLastSlide ? (\n                <>\n                  <span>Iniciar Missão</span>\n                  <Search className=\"w-4 h-4\" />\n                </>\n              ) : (\n                <>\n                  <span>Próximo</span>\n                  <ChevronRight className=\"w-4 h-4\" />\n                </>\n              )}\n            </button>\n          </div>\n\n        </div>\n      </div>\n    </div>\n  );\n};\n",
  "src/components/ExamSheet.tsx": "import React, { useEffect, useRef, useState } from 'react';\nimport { Evidence } from '../types';\nimport { formatTime, PHOTOS, SVGS } from '../data/evidence';\nimport { Mic, Volume2, Pause, RotateCcw, Disc, FileText } from 'lucide-react';\nimport { useScrollLock } from '../hooks/useScrollLock';\n\ninterface ExamSheetProps {\n  evidence: Evidence | null;\n  sequence: string[];\n  isOpen: boolean;\n  onClose: () => void;\n  onAddToSeq: (evId: string) => void;\n  onMoveSeq: (evId: string, dir: number) => void;\n  onRemoveFromSeq: (evId: string) => void;\n  onOpenRetroSheet?: () => void;\n}\n\nexport const ExamSheet: React.FC<ExamSheetProps> = ({\n  evidence,\n  sequence,\n  isOpen,\n  onClose,\n  onAddToSeq,\n  onMoveSeq,\n  onRemoveFromSeq,\n  onOpenRetroSheet,\n}) => {\n  const [isPlaying, setIsPlaying] = useState(false);\n  const [elapsed, setElapsed] = useState(0);\n  const timerRef = useRef<number | null>(null);\n  const startTimeRef = useRef<number>(0);\n\n  // Rigid scroll lock on mobile & desktop\n  useScrollLock(isOpen);\n\n  const duration = evidence ? Math.max(4, Math.round(evidence.desc.length / 15)) : 0;\n\n  const stopAudio = () => {\n    if (typeof window !== 'undefined' && window.speechSynthesis) {\n      window.speechSynthesis.cancel();\n    }\n    setIsPlaying(false);\n    if (timerRef.current) {\n      clearInterval(timerRef.current);\n      timerRef.current = null;\n    }\n    setElapsed(0);\n  };\n\n  useEffect(() => {\n    stopAudio();\n    return () => {\n      stopAudio();\n    };\n  }, [evidence?.id, isOpen]);\n\n  const toggleAudio = () => {\n    if (!evidence) return;\n    if (isPlaying) {\n      stopAudio();\n      return;\n    }\n\n    if (typeof window === 'undefined' || !window.speechSynthesis) {\n      return;\n    }\n\n    window.speechSynthesis.cancel();\n    const utterance = new SpeechSynthesisUtterance(evidence.desc);\n    utterance.lang = 'pt-BR';\n    utterance.rate = 0.88;\n    utterance.pitch = 0.92;\n\n    utterance.onstart = () => {\n      setIsPlaying(true);\n      startTimeRef.current = Date.now();\n      timerRef.current = window.setInterval(() => {\n        const diff = (Date.now() - startTimeRef.current) / 1000;\n        if (diff >= duration) {\n          setElapsed(duration);\n        } else {\n          setElapsed(diff);\n        }\n      }, 100);\n    };\n\n    utterance.onend = () => {\n      stopAudio();\n      setElapsed(duration);\n    };\n\n    utterance.onerror = () => {\n      stopAudio();\n    };\n\n    window.speechSynthesis.speak(utterance);\n  };\n\n  if (!isOpen || !evidence) return null;\n\n  const photo = PHOTOS[evidence.id];\n  const svgRaw = SVGS[evidence.id];\n  const seqIdx = sequence.indexOf(evidence.id);\n  const inSeq = seqIdx !== -1;\n  const progressRatio = duration > 0 ? Math.min(elapsed / duration, 1) : 0;\n\n  return (\n    <>\n      <div\n        id=\"backdrop\"\n        onClick={() => {\n          stopAudio();\n          onClose();\n        }}\n        onTouchMove={(e) => {\n          e.preventDefault();\n        }}\n        className=\"fixed inset-0 z-[200] bg-black/80 backdrop-blur-[2px] transition-opacity duration-300\"\n        aria-hidden=\"true\"\n      />\n\n      <div\n        id=\"sheet\"\n        role=\"dialog\"\n        aria-modal=\"true\"\n        aria-label=\"Exame de evidência\"\n        className=\"fixed bottom-0 left-0 right-0 z-[300] bg-[#222222] rounded-t-[20px] max-h-[92vh] overflow-y-auto overscroll-contain touch-pan-y sm:left-1/2 sm:-translate-x-1/2 sm:max-w-[620px] sm:shadow-[0_-8px_40px_rgba(0,0,0,0.7)] pb-6 sm:pb-8 transition-transform duration-300 animate-fadeup\"\n      >\n        <div className=\"sticky top-0 z-[2] bg-[#222222] flex items-center justify-between p-[14px_20px_12px] border-b border-[#303030]\">\n          <div className=\"w-[36px] h-[4px] rounded-[2px] bg-[#303030] absolute top-[10px] left-1/2 -translate-x-1/2\" aria-hidden=\"true\" />\n          <div className=\"text-center flex-1\">\n            <div className=\"font-mono-retro text-[12px] tracking-[0.14em] text-[#9A9590] uppercase\">\n              EVIDÊNCIA {evidence.id}\n            </div>\n            <div className=\"font-brunson text-[26px] uppercase tracking-[0.04em] leading-none text-[#F2EAE0]\">\n              {evidence.tipo}\n            </div>\n          </div>\n          <button\n            type=\"button\"\n            onClick={() => {\n              stopAudio();\n              onClose();\n            }}\n            aria-label=\"Fechar\"\n            className=\"w-[40px] h-[40px] rounded-full bg-[#2C2626] border border-[#303030] text-[#F2EAE0] text-[22px] cursor-pointer flex items-center justify-center hover:bg-[#3A1010] transition-colors flex-shrink-0 leading-none\"\n          >\n            ×\n          </button>\n        </div>\n\n        <div className=\"relative overflow-hidden bg-[#0D0D0D] border-b border-[#222222]\">\n          {photo ? (\n            <img\n              src={photo}\n              alt={evidence.tipo}\n              className=\"block w-full h-auto max-h-[360px] object-contain mx-auto\"\n            />\n          ) : svgRaw ? (\n            <div\n              dangerouslySetInnerHTML={{\n                __html: svgRaw\n                  .replace(/id=\"g(\\w+)\"/g, `id=\"g$1-${evidence.id}-exam\"`)\n                  .replace(/url\\(#g(\\w+)\\)/g, `url(#g$1-${evidence.id}-exam)`),\n              }}\n              className=\"block w-full h-auto\"\n            />\n          ) : (\n            <div className=\"h-[180px] flex items-center justify-center font-mono-retro text-[13px] text-[#303030]\">\n              [ FOTO ]\n            </div>\n          )}\n\n          <div className=\"absolute top-[10px] left-[10px] z-[2] font-mono-retro text-[11px] text-[#F2EAE0] bg-[#0D0D0D]/85 px-[10px] py-[4px] rounded-[4px] flex items-center gap-[6px] tracking-[0.05em]\">\n            <span className=\"rec-dot !w-[7px] !h-[7px]\" aria-hidden=\"true\" />\n            REC · {evidence.id}\n          </div>\n        </div>\n\n        <div className=\"p-[14px_14px] sm:p-[18px_20px] flex flex-col gap-[12px] sm:gap-[14px]\">\n          <div className=\"bg-[#16171b] border-2 border-[#2d3038] rounded-[14px] p-3.5 sm:p-4 shadow-[inset_0_1px_1px_rgba(255,255,255,0.08),0_8px_20px_rgba(0,0,0,0.6)] relative overflow-hidden\">\n            \n            <div className=\"flex items-center justify-between gap-2 pb-2.5 mb-3 border-b border-[#282b33]\">\n              <div className=\"flex items-center gap-2\">\n                <div className=\"w-2.5 h-2.5 rounded-full bg-[#111] border border-[#444] flex items-center justify-center\">\n                  <div className={`w-1.5 h-1.5 rounded-full transition-all ${\n                    isPlaying ? 'bg-[#ff3b30] shadow-[0_0_8px_#ff3b30] animate-pulse' : 'bg-[#402020]'\n                  }`} />\n                </div>\n                <span className=\"font-mono-retro text-[10px] sm:text-[11px] uppercase tracking-[0.14em] text-[#9A9590] font-semibold flex items-center gap-1.5\">\n                  <Mic className=\"w-3.5 h-3.5 text-[#d94040]\" />\n                  Gravador Policial · {evidence.id}\n                </span>\n              </div>\n\n              <div className=\"flex items-center gap-2 bg-[#0d0e11] px-2.5 py-1 rounded-[5px] border border-[#22252c]\">\n                <span className=\"font-mono-retro text-[11px] tracking-[0.08em] text-[#7DD5D8] font-bold\">\n                  {formatTime(elapsed)} / {formatTime(duration)}\n                </span>\n                <div className={`reel ${isPlaying ? 'reel-spin' : ''}`} aria-hidden=\"true\">\n                  <Disc className={`w-4 h-4 text-[#8a8f9d] ${isPlaying ? 'text-[#7DD5D8]' : ''}`} />\n                </div>\n              </div>\n            </div>\n\n            <div className=\"bg-[#0b0c0e] border border-[#22252e] rounded-[8px] p-2.5 mb-3 flex items-center gap-3\">\n              <div className=\"hidden sm:flex items-center justify-between w-[60px] h-[30px] bg-[#14161b] border border-[#2a2d36] rounded-[4px] px-1.5 flex-shrink-0 relative overflow-hidden\">\n                <div className=\"absolute inset-x-2 top-1/2 -translate-y-1/2 h-[2px] bg-[#4a2a18]\" />\n                <Disc className={`w-4 h-4 text-[#6a7080] z-10 ${isPlaying ? 'animate-spin' : ''}`} style={{ animationDuration: '2s' }} />\n                <Disc className={`w-4 h-4 text-[#6a7080] z-10 ${isPlaying ? 'animate-spin' : ''}`} style={{ animationDuration: '2s' }} />\n              </div>\n\n              <div className=\"flex-1 flex flex-col gap-1\">\n                <div className={`flex items-end gap-[2px] h-[26px] w-full ${isPlaying ? 'audio-playing' : ''}`} aria-hidden=\"true\">\n                  {Array.from({ length: 28 }, (_, j) => {\n                    const barCut = Math.round(progressRatio * 28);\n                    const isBarPlayed = j < barCut;\n                    const delay = (j * 0.03 + (j % 3) * 0.04).toFixed(3);\n                    return (\n                      <div\n                        key={j}\n                        className={`wave-bar ${isBarPlayed ? 'played' : 'rem'}`}\n                        style={{ '--d': `${delay}s` } as React.CSSProperties}\n                      />\n                    );\n                  })}\n                </div>\n              </div>\n            </div>\n\n            <div className=\"flex items-center gap-2 flex-wrap sm:flex-nowrap\">\n              <button\n                type=\"button\"\n                onClick={toggleAudio}\n                aria-label={isPlaying ? \"Pausar gravação policial\" : \"Ouvir gravação de depoimento policial\"}\n                className={`flex-1 min-h-[44px] px-4 rounded-[8px] font-mono-retro text-[12px] sm:text-[13px] font-bold uppercase tracking-[0.08em] cursor-pointer flex items-center justify-center gap-2.5 transition-all duration-150 select-none border-t border-l ${\n                  isPlaying\n                    ? 'bg-[#d94040] text-white border-t-[#ff6666] border-l-[#ff6666] border-r-[#802020] border-b-[#802020] shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)] translate-y-[1px]'\n                    : 'bg-gradient-to-b from-[#343842] via-[#282c35] to-[#1c2028] text-[#F2EAE0] border-t-[#4a505e] border-l-[#4a505e] border-r-[#121419] border-b-[#121419] hover:from-[#3d424e] hover:to-[#222630] active:translate-y-[1px] shadow-[0_3px_6px_rgba(0,0,0,0.4)]'\n                } focus-visible:outline focus-visible:outline-2 focus-visible:outline-[#7DD5D8]`}\n              >\n                {isPlaying ? (\n                  <>\n                    <Pause className=\"w-4 h-4 fill-current text-white flex-shrink-0\" />\n                    <span>Pausar Depoimento</span>\n                  </>\n                ) : (\n                  <>\n                    <Volume2 className=\"w-4 h-4 text-[#7DD5D8] flex-shrink-0\" />\n                    <span>Ouvir Gravação</span>\n                  </>\n                )}\n              </button>\n\n              <button\n                type=\"button\"\n                onClick={() => {\n                  stopAudio();\n                  toggleAudio();\n                }}\n                title=\"Reiniciar depoimento do início\"\n                aria-label=\"Reiniciar depoimento do início\"\n                className=\"h-[44px] px-3.5 rounded-[8px] bg-gradient-to-b from-[#2a2d36] to-[#1a1c22] border-t border-l border-t-[#3e4250] border-l-[#3e4250] border-r-[#101115] border-b-[#101115] text-[#9A9590] hover:text-[#F2EAE0] hover:from-[#323642] active:translate-y-[1px] flex items-center justify-center gap-1.5 font-mono-retro text-[11px] uppercase tracking-[0.05em] cursor-pointer transition-all flex-shrink-0 shadow-[0_3px_6px_rgba(0,0,0,0.4)]\"\n              >\n                <RotateCcw className=\"w-3.5 h-3.5\" />\n                <span className=\"hidden sm:inline\">Reiniciar</span>\n              </button>\n            </div>\n          </div>\n\n          <div className=\"bg-[#E8DFC8] border-2 border-[#cfc4a9] rounded-[11px] p-4 sm:p-5 shadow-inner relative overflow-hidden\">\n            <div className=\"flex items-center justify-between pb-2 mb-2.5 border-b border-[#c8be9f]\">\n              <span className=\"font-mono-retro text-[10px] sm:text-[11px] uppercase tracking-[0.16em] text-[#6b5838] font-bold flex items-center gap-1.5\">\n                <FileText className=\"w-3.5 h-3.5 text-[#8c6b32]\" />\n                Laudo de Cena · Evidência {evidence.id}\n              </span>\n              <span className=\"font-mono-retro text-[9px] uppercase tracking-[0.12em] text-[#8c7e63] bg-[#dbd0b6] px-2 py-0.5 rounded font-semibold\">\n                {evidence.tipo}\n              </span>\n            </div>\n\n            <p className=\"font-mono-retro text-[14px] sm:text-[15px] text-[#241a12] leading-[1.8] font-normal\">\n              \"{evidence.desc}\"\n            </p>\n          </div>\n\n          {evidence.id === 'E-15' && onOpenRetroSheet && (\n            <button\n              type=\"button\"\n              onClick={onOpenRetroSheet}\n              className=\"bg-[#008080] text-white border-2 border-t-white border-l-white border-r-black border-b-black p-3 font-mono-retro text-[13px] flex items-center justify-center gap-2 hover:bg-[#006666] active:border-t-black active:border-l-black active:border-r-white active:border-b-white transition-all shadow-md\"\n            >\n              <span>📊</span>\n              <span>Abrir no RetroSheet 95 (Planilha original de despesas)</span>\n            </button>\n          )}\n\n          <div className=\"bg-[#2C2626] border border-[#303030] rounded-[10px] p-[12px_16px] flex items-center gap-3 flex-wrap min-h-[54px]\">\n            {!inSeq ? (\n              <>\n                <span className=\"font-mono-retro text-[12px] tracking-[0.1em] uppercase text-[#9A9590] flex-shrink-0\">\n                  Linha do tempo\n                </span>\n                <button\n                  type=\"button\"\n                  onClick={() => onAddToSeq(evidence.id)}\n                  className=\"flex-1 min-w-[130px] h-[40px] px-3 rounded-[8px] bg-[#D94040] text-white border-none font-inherit text-[12px] sm:text-[13px] font-bold uppercase tracking-[0.07em] cursor-pointer hover:bg-[#c03434] transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-[#7DD5D8] whitespace-nowrap flex items-center justify-center\"\n                >\n                  + Adicionar à sequência\n                </button>\n              </>\n            ) : (\n              <>\n                <span className=\"font-mono-retro text-[12px] tracking-[0.1em] uppercase text-[#9A9590] flex-shrink-0\">\n                  Posição <span className=\"text-[#7DD5D8] text-[15px] font-bold\">#{seqIdx + 1}</span> de {sequence.length}\n                </span>\n                <div className=\"flex gap-[6px] items-center flex-1 justify-end flex-wrap\">\n                  <button\n                    type=\"button\"\n                    disabled={seqIdx === 0}\n                    onClick={() => onMoveSeq(evidence.id, -1)}\n                    aria-label=\"Mover para antes\"\n                    className=\"w-[34px] h-[34px] rounded-[7px] bg-transparent border border-[#303030] text-[#F2EAE0] cursor-pointer text-[15px] flex items-center justify-center hover:bg-[#181818] disabled:opacity-25 disabled:cursor-default transition-colors\"\n                  >\n                    ←\n                  </button>\n                  <button\n                    type=\"button\"\n                    disabled={seqIdx === sequence.length - 1}\n                    onClick={() => onMoveSeq(evidence.id, 1)}\n                    aria-label=\"Mover para depois\"\n                    className=\"w-[34px] h-[34px] rounded-[7px] bg-transparent border border-[#303030] text-[#F2EAE0] cursor-pointer text-[15px] flex items-center justify-center hover:bg-[#181818] disabled:opacity-25 disabled:cursor-default transition-colors\"\n                  >\n                    →\n                  </button>\n                  <button\n                    type=\"button\"\n                    onClick={() => onRemoveFromSeq(evidence.id)}\n                    className=\"h-[34px] px-[12px] rounded-[7px] bg-transparent border border-[#303030] text-[#9A9590] cursor-pointer text-[12px] font-mono-retro hover:border-[#E57373] hover:text-[#E57373] transition-all\"\n                  >\n                    Remover\n                  </button>\n                </div>\n              </>\n            )}\n          </div>\n        </div>\n      </div>\n    </>\n  );\n};\n",
  "src/components/ResultModal.tsx": "import React from 'react';\nimport { FinalVerificationResult } from '../types';\nimport { FileText, CheckCircle2, XCircle, AlertCircle, RotateCcw, Home, ArrowLeft } from 'lucide-react';\nimport { useScrollLock } from '../hooks/useScrollLock';\n\ninterface ResultModalProps {\n  result: FinalVerificationResult | null;\n  isOpen: boolean;\n  onClose: () => void;\n  onRestart: () => void;\n  onGoHome: () => void;\n}\n\nexport const ResultModal: React.FC<ResultModalProps> = ({\n  result,\n  isOpen,\n  onClose,\n  onRestart,\n  onGoHome,\n}) => {\n  useScrollLock(isOpen);\n\n  if (!isOpen || !result) return null;\n\n  const isPerfect = result.pct >= 85;\n\n  return (\n    <div\n      id=\"result\"\n      role=\"dialog\"\n      aria-modal=\"true\"\n      aria-label=\"Laudo Pericial da Investigação\"\n      onTouchMove={(e) => {\n        if (e.target === e.currentTarget) {\n          e.preventDefault();\n        }\n      }}\n      className=\"fixed inset-0 z-[2000] bg-black/90 backdrop-blur-md overflow-y-auto overscroll-contain touch-pan-y p-3 sm:p-6 flex justify-center animate-fadeup\"\n    >\n      <div id=\"result-box\" className=\"max-w-[760px] w-full my-auto py-4\">\n        <div className=\"bg-[#121318] border-2 border-[#2b2d38] rounded-[18px] shadow-[0_20px_70px_rgba(0,0,0,0.9)] overflow-hidden\">\n          \n          <div className=\"bg-[#07080a] border-b border-[#20222a] p-[14px_20px] flex items-center justify-between gap-3\">\n            <div className=\"flex items-center gap-2\">\n              <FileText className=\"w-4 h-4 text-[#7DD5D8]\" />\n              <span className=\"font-mono-retro text-[10px] sm:text-[11px] tracking-[0.18em] uppercase text-[#7DD5D8] font-bold\">\n                SECRETARIA DE SEGURANÇA PÚBLICA · POLÍCIA TÉCNICA 1995\n              </span>\n            </div>\n\n            <button\n              type=\"button\"\n              onClick={onClose}\n              aria-label=\"Fechar e revisar fichas\"\n              className=\"w-[34px] h-[34px] rounded-full bg-[#1b1c24] border border-[#343846] text-[#F2EAE0] text-[18px] cursor-pointer flex items-center justify-center hover:bg-[#d94040] hover:text-white hover:border-[#d94040] transition-colors leading-none flex-shrink-0\"\n              title=\"Fechar laudo pericial\"\n            >\n              ×\n            </button>\n          </div>\n\n          <div className=\"p-4 sm:p-7 flex flex-col gap-5\">\n            \n            <div className=\"flex flex-col sm:flex-row sm:items-end justify-between gap-4 pb-4 border-b border-[#232530]\">\n              <div>\n                <span className=\"font-mono-retro text-[10px] sm:text-[11px] tracking-[0.2em] text-[#9A9590] uppercase font-bold\">\n                  AUTÓPSIA & CONGRUÊNCIA DE DADOS · CASO Nº 139\n                </span>\n                <h2 className=\"font-brunson text-[34px] sm:text-[46px] uppercase tracking-[0.03em] leading-[0.95] text-[#F2EAE0] mt-1\">\n                  Laudo Pericial\n                </h2>\n              </div>\n\n              <div\n                className=\"inline-flex items-center gap-2 font-mono-retro text-[11px] sm:text-[13px] tracking-[0.22em] uppercase border-2 px-4 py-2 rounded-[8px] -rotate-[1.5deg] origin-left font-bold shadow-md bg-[#0a0b0e]\"\n                style={{ color: result.color, borderColor: result.color }}\n              >\n                <span>{result.stamp}</span>\n              </div>\n            </div>\n\n            <div className=\"bg-[#090a0d] border-2 border-[#232632] rounded-[14px] p-4 sm:p-5 flex flex-col gap-4 shadow-inner\">\n              <div className=\"flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4\">\n                \n                <div className=\"flex flex-col sm:flex-row items-stretch sm:items-center gap-3 w-full sm:w-auto\">\n                  <div className=\"bg-[#14161f] border border-[#2d3142] px-4 py-2.5 rounded-[10px] text-center w-full sm:w-auto sm:min-w-[130px] flex sm:flex-col items-center justify-between sm:justify-center gap-2 sm:gap-0 shadow-sm\">\n                    <span className=\"font-brunson text-[38px] sm:text-[50px] leading-none text-[#F2EAE0]\">\n                      {result.scoreCor}/{result.scoreTot}\n                    </span>\n                    <span className=\"font-mono-retro text-[10px] sm:text-[9px] uppercase tracking-[0.14em] text-[#7DD5D8] font-bold\">\n                      Campos Validados\n                    </span>\n                  </div>\n\n                  <div className=\"font-mono-retro text-[12px] sm:text-[13px] text-[#a0a0b0] leading-[1.6] flex flex-col gap-1.5 bg-[#12141c] sm:bg-transparent p-3 sm:p-0 rounded-[9px] border sm:border-none border-[#222532]\">\n                    <div className=\"flex items-center gap-2\">\n                      <span className=\"w-2 h-2 rounded-full bg-[#4CAF50] flex-shrink-0\" />\n                      <span><strong className=\"text-[#F2EAE0]\">{result.scoreCor} de {result.scoreTot}</strong> acertos nas Fichas</span>\n                    </div>\n                    <div className=\"flex items-center gap-2 text-[#7DD5D8]\">\n                      <span className=\"w-2 h-2 rounded-full bg-[#7DD5D8] flex-shrink-0\" />\n                      <span><strong className=\"text-[#F2EAE0]\">{result.seqHits} de 21</strong> fitas na Sequência</span>\n                    </div>\n                  </div>\n                </div>\n\n                <div className=\"w-full sm:w-[220px] flex flex-col gap-2 bg-[#12141c] p-3 rounded-[10px] border border-[#232634]\">\n                  <div>\n                    <div className=\"flex justify-between font-mono-retro text-[10px] text-[#a0a0b0] font-bold mb-1 uppercase\">\n                      <span>Fichas dos Personagens</span>\n                      <span style={{ color: result.color }}>{result.pct}%</span>\n                    </div>\n                    <div className=\"w-full bg-[#08090c] h-2 rounded-full overflow-hidden border border-[#20222e]\">\n                      <div\n                        className=\"h-full transition-all duration-500\"\n                        style={{ width: `${result.pct}%`, backgroundColor: result.color }}\n                      />\n                    </div>\n                  </div>\n\n                  <div>\n                    <div className=\"flex justify-between font-mono-retro text-[10px] text-[#a0a0b0] font-bold mb-1 uppercase\">\n                      <span>Sequência de Fitas VHS</span>\n                      <span className=\"text-[#7DD5D8]\">{result.seqPct}%</span>\n                    </div>\n                    <div className=\"w-full bg-[#08090c] h-2 rounded-full overflow-hidden border border-[#20222e]\">\n                      <div\n                        className=\"h-full bg-[#7DD5D8] transition-all duration-500\"\n                        style={{ width: `${result.seqPct}%` }}\n                      />\n                    </div>\n                  </div>\n                </div>\n              </div>\n\n              <div\n                className=\"font-mono-retro text-[12px] sm:text-[13px] text-[#d4cfc5] leading-[1.7] bg-[#14151c] p-3.5 rounded-[10px] border border-[#262836]\"\n                dangerouslySetInnerHTML={{ __html: result.info }}\n              />\n            </div>\n\n            <div id=\"res-detalhe\" className=\"flex flex-col gap-4\">\n              <div className=\"font-mono-retro text-[11px] tracking-[0.16em] uppercase text-[#7DD5D8] font-bold flex items-center gap-2 pb-1 border-b border-[#232530]\">\n                <span>📋 ANÁLISE DETALHADA POR PERSONAGEM</span>\n              </div>\n\n              {result.details.map(({ p, campos, especial }) => (\n                <div\n                  key={p.id}\n                  className=\"bg-[#090a0d] border-2 border-[#232632] rounded-[14px] overflow-hidden shadow-md\"\n                >\n                  <div\n                    className=\"p-[10px_16px] flex items-center justify-between border-b border-[#20222e]\"\n                    style={{\n                      borderLeft: `5px solid ${p.cor}`,\n                      backgroundColor: `${p.cor}15`,\n                    }}\n                  >\n                    <div className=\"flex items-center gap-2.5\">\n                      <span\n                        className=\"w-3 h-3 rounded-full flex-shrink-0\"\n                        style={{ backgroundColor: p.cor }}\n                      />\n                      <h3\n                        className=\"font-brunson text-[22px] sm:text-[26px] tracking-[0.04em] uppercase leading-none\"\n                        style={{ color: p.cor }}\n                      >\n                        {p.nome}\n                      </h3>\n                    </div>\n\n                    <span className=\"font-mono-retro text-[10px] tracking-[0.12em] uppercase text-[#808095] bg-[#14151e] px-2.5 py-1 rounded border border-[#262836] font-semibold\">\n                      DOSSIÊ · {p.id}\n                    </span>\n                  </div>\n\n                  <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-2 p-3 bg-[#0d0e12]\">\n                    {campos.map((c, idx) => {\n                      const isOk = c.cls === 'ok';\n                      const isErr = c.cls === 'err';\n                      const isAmb = c.cls === 'amb';\n\n                      return (\n                        <div\n                          key={idx}\n                          className={`p-3 rounded-[10px] border-2 font-mono-retro flex flex-col gap-1 transition-all ${\n                            isOk\n                              ? 'bg-[#0b160e] border-[#1e4028] text-[#e0f7e4]'\n                              : isErr\n                              ? 'bg-[#1c0d0f] border-[#4a1c1e] text-[#fce8e8]'\n                              : 'bg-[#18140a] border-[#4a3d1c] text-[#fef5e6]'\n                          }`}\n                        >\n                          <div className=\"flex items-center justify-between pb-1 border-b border-white/10\">\n                            <span className=\"text-[10px] uppercase tracking-[0.14em] font-bold text-[#a0a0b0]\">\n                              {c.label}\n                            </span>\n\n                            {isOk && (\n                              <span className=\"text-[10px] font-bold uppercase tracking-[0.08em] text-[#4CAF50] flex items-center gap-1\">\n                                <CheckCircle2 className=\"w-3 h-3\" />\n                                Validado\n                              </span>\n                            )}\n                            {isErr && (\n                              <span className=\"text-[10px] font-bold uppercase tracking-[0.08em] text-[#E57373] flex items-center gap-1\">\n                                <XCircle className=\"w-3 h-3\" />\n                                Divergência\n                              </span>\n                            )}\n                            {isAmb && (\n                              <span className=\"text-[10px] font-bold uppercase tracking-[0.08em] text-[#FFB74D] flex items-center gap-1\">\n                                <AlertCircle className=\"w-3 h-3\" />\n                                Ambíguo\n                              </span>\n                            )}\n                          </div>\n\n                          <div className=\"text-[13px] font-bold mt-1 leading-snug\">\n                            \"{c.val || '— não respondido —'}\"\n                          </div>\n\n                          {isErr && c.hint && (\n                            <div className=\"mt-2 bg-[#0d0708] border border-[#602528] p-2 rounded-[6px] text-[11px] text-[#f5a6a6] leading-[1.5] italic\">\n                              💡 <strong>Pista do Laudo:</strong> {c.hint}\n                            </div>\n                          )}\n\n                          {isAmb && (\n                            <div className=\"mt-2 bg-[#120f06] border border-[#604f25] p-2 rounded-[6px] text-[11px] text-[#ffd699] leading-[1.5] italic\">\n                              ⚠ Evidência E-21 confirma dupla possibilidade aceita.\n                            </div>\n                          )}\n                        </div>\n                      );\n                    })}\n                  </div>\n\n                  {especial && (\n                    <div className=\"bg-[#141208] border-t border-[#3d3315] p-3 text-[11px] text-[#ffd899] font-mono-retro italic leading-[1.6]\">\n                      ⚠ A morte de {p.nome} é intencionalmente ambígua conforme o laudo pericial final (Evidência E-21). Tanto Vera quanto Cláudio são aceitos como resposta válida para o confronto das 5h40.\n                    </div>\n                  )}\n                </div>\n              ))}\n            </div>\n\n            <div className=\"flex flex-col gap-2.5 pt-3 border-t border-[#232530]\">\n              <button\n                type=\"button\"\n                onClick={onClose}\n                className=\"w-full min-h-[48px] px-4 rounded-[12px] bg-[#7DD5D8] text-[#0D0D0D] font-mono-retro text-[13px] font-bold uppercase tracking-[0.08em] cursor-pointer hover:bg-[#9DE0E3] transition-all flex items-center justify-center gap-2 shadow-[0_4px_16px_rgba(125,213,216,0.25)]\"\n              >\n                <ArrowLeft className=\"w-4 h-4 text-[#0D0D0D]\" />\n                <span>Voltar para Corrigir Fichas</span>\n              </button>\n\n              <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-2.5\">\n                <button\n                  type=\"button\"\n                  onClick={onRestart}\n                  className=\"w-full h-[44px] px-3 rounded-[10px] bg-[#1a1c24] border border-[#343848] text-[#F2EAE0] hover:text-white hover:border-[#7DD5D8] font-mono-retro text-[11px] uppercase tracking-[0.08em] font-semibold cursor-pointer transition-all flex items-center justify-center gap-1.5\"\n                >\n                  <RotateCcw className=\"w-3.5 h-3.5\" />\n                  <span>Reiniciar do Zero</span>\n                </button>\n\n                <button\n                  type=\"button\"\n                  onClick={onGoHome}\n                  className=\"w-full h-[44px] px-3 rounded-[10px] bg-transparent border border-[#2b2d38] text-[#9A9590] hover:text-[#F2EAE0] hover:border-[#606070] font-mono-retro text-[11px] uppercase tracking-[0.08em] cursor-pointer transition-all flex items-center justify-center gap-1.5\"\n                >\n                  <Home className=\"w-3.5 h-3.5\" />\n                  <span>Tela Inicial</span>\n                </button>\n              </div>\n            </div>\n\n          </div>\n        </div>\n      </div>\n    </div>\n  );\n};\n",
  "src/components/DetectiveVictoryModal.tsx": "import React, { useState, useEffect, useRef } from 'react';\nimport { FileText, RotateCcw, Trophy, Sparkles } from 'lucide-react';\nimport { useScrollLock } from '../hooks/useScrollLock';\n\ninterface DetectiveVictoryModalProps {\n  isOpen: boolean;\n  onReview: () => void;\n  onRestart: () => void;\n}\n\nexport const DetectiveVictoryModal: React.FC<DetectiveVictoryModalProps> = ({\n  isOpen,\n  onReview,\n  onRestart,\n}) => {\n  useScrollLock(isOpen);\n\n  const [currentFrame, setCurrentFrame] = useState(0);\n  const canvasRef = useRef<HTMLCanvasElement>(null);\n  const imgRef = useRef<HTMLImageElement | null>(null);\n\n  useEffect(() => {\n    const img = new Image();\n    img.src = '/assets/aistudio/Detetive_Pixelado_no_Ref_gio_Aconchegante_674d8c38.png';\n    img.onload = () => {\n      imgRef.current = img;\n    };\n  }, []);\n\n  useEffect(() => {\n    if (!isOpen) return;\n\n    setCurrentFrame(0);\n    const interval = setInterval(() => {\n      setCurrentFrame((prev) => (prev + 1) % 8);\n    }, 220);\n\n    return () => {\n      clearInterval(interval);\n    };\n  }, [isOpen]);\n\n  useEffect(() => {\n    if (!isOpen) return;\n    const canvas = canvasRef.current;\n    const img = imgRef.current;\n    if (!canvas || !img || !img.complete) return;\n\n    const ctx = canvas.getContext('2d');\n    if (!ctx) return;\n\n    const cols = 4;\n    const rows = 2;\n    const frameW = img.width / cols;\n    const frameH = img.height / rows;\n\n    const col = currentFrame % cols;\n    const row = Math.floor(currentFrame / cols);\n\n    canvas.width = frameW;\n    canvas.height = frameH;\n\n    ctx.imageSmoothingEnabled = false;\n    ctx.clearRect(0, 0, frameW, frameH);\n    ctx.drawImage(\n      img,\n      col * frameW,\n      row * frameH,\n      frameW,\n      frameH,\n      0,\n      0,\n      frameW,\n      frameH\n    );\n  }, [currentFrame, isOpen]);\n\n  if (!isOpen) return null;\n\n  return (\n    <div\n      className=\"fixed inset-0 z-[2500] bg-black/90 backdrop-blur-md flex items-center justify-center p-3 sm:p-5 overflow-y-auto overscroll-contain touch-pan-y animate-fadeIn\"\n      role=\"dialog\"\n      aria-modal=\"true\"\n      aria-label=\"Investigação Solucionada\"\n      onTouchMove={(e) => {\n        if (e.target === e.currentTarget) {\n          e.preventDefault();\n        }\n      }}\n    >\n      <div className=\"w-full max-w-[560px] bg-[#0c0d10] border-2 border-[#1e4840] rounded-[16px] shadow-[0_16px_60px_rgba(0,0,0,0.9)] overflow-hidden flex flex-col my-auto relative\">\n        \n        <div className=\"bg-[#070b09] border-b border-[#183a33] p-[12px_18px] flex items-center justify-between gap-3\">\n          <div className=\"flex items-center gap-2\">\n            <Trophy className=\"w-4 h-4 text-[#7DD5D8]\" />\n            <span className=\"font-mono-retro text-[11px] sm:text-[12px] tracking-[0.16em] uppercase text-[#7DD5D8] font-bold\">\n              CASO SOLUCIONADO · 1995\n            </span>\n          </div>\n\n          <span className=\"font-mono-retro text-[10px] tracking-[0.08em] text-[#D4AF37] uppercase font-bold flex items-center gap-1\">\n            <Sparkles className=\"w-3 h-3 text-[#D4AF37]\" />\n            ARQUIVO CONCLUÍDO\n          </span>\n        </div>\n\n        <div className=\"p-4 sm:p-6 flex flex-col gap-4\">\n          \n          <div className=\"text-center flex flex-col items-center\">\n            <h2 className=\"font-brunson text-[32px] sm:text-[40px] uppercase tracking-[0.04em] leading-[0.95] text-[#7DD5D8] mb-2.5 drop-shadow-[0_2px_10px_rgba(125,213,216,0.3)]\">\n              Investigação<br />Solucionada!\n            </h2>\n            <p className=\"font-mono-retro text-[12px] sm:text-[13px] text-[#c2cfcd] leading-[1.7] italic max-w-[460px]\">\n              \"Um brinde à verdade! Todas as evidências foram conectadas com precisão pericial e a linha do tempo do Rancho Esperança foi completamente desvendada. O mistério acabou.\"\n            </p>\n          </div>\n\n          <div className=\"relative h-[250px] sm:h-[280px] w-full bg-[#000000] border border-[#20222a] rounded-[12px] flex items-center justify-center overflow-hidden\">\n            \n            <canvas\n              ref={canvasRef}\n              className=\"h-[240px] sm:h-[270px] w-auto object-contain\"\n              style={{ imageRendering: 'pixelated' }}\n            />\n\n            <div className=\"absolute bottom-2.5 right-3 z-30 font-mono-retro text-[9px] uppercase tracking-[0.14em] text-[#D4AF37] bg-[#0c0d10]/90 px-2.5 py-1 rounded border border-[#3d2e14] font-bold shadow-md\">\n              DETETIVE · CASO RESOLVIDO 🥂\n            </div>\n          </div>\n\n          <div className=\"flex flex-col gap-2.5 pt-1\">\n            <button\n              type=\"button\"\n              onClick={onReview}\n              className=\"w-full h-[48px] rounded-[10px] bg-[#7DD5D8] text-[#0D0D0D] font-mono-retro text-[12px] sm:text-[13px] font-bold uppercase tracking-[0.08em] cursor-pointer hover:bg-[#9DE0E3] transition-all flex items-center justify-center gap-2 shadow-[0_4px_16px_rgba(125,213,216,0.3)]\"\n            >\n              <FileText className=\"w-4 h-4 text-[#0D0D0D]\" />\n              <span>Ver Laudo Final de Autópsia</span>\n            </button>\n\n            <button\n              type=\"button\"\n              onClick={onRestart}\n              className=\"w-full h-[42px] rounded-[10px] bg-transparent border border-[#2b2d38] text-[#9A9590] font-mono-retro text-[11px] uppercase tracking-[0.08em] cursor-pointer hover:text-[#F2EAE0] hover:border-[#606070] transition-all flex items-center justify-center gap-1.5\"\n            >\n              <RotateCcw className=\"w-3.5 h-3.5\" />\n              <span>Jogar Novamente (Reiniciar Caso)</span>\n            </button>\n          </div>\n\n        </div>\n      </div>\n    </div>\n  );\n};\n",
  "src/components/DetectiveDefeatModal.tsx": "import React, { useState, useEffect } from 'react';\nimport { FileText, RotateCcw, AlertTriangle } from 'lucide-react';\nimport { useScrollLock } from '../hooks/useScrollLock';\n\ninterface DetectiveDefeatModalProps {\n  isOpen: boolean;\n  onReview: () => void;\n  onRestart: () => void;\n}\n\nexport const DetectiveDefeatModal: React.FC<DetectiveDefeatModalProps> = ({\n  isOpen,\n  onReview,\n  onRestart,\n}) => {\n  useScrollLock(isOpen);\n\n  const [currentFrame, setCurrentFrame] = useState(0);\n\n  useEffect(() => {\n    if (!isOpen) return;\n\n    setCurrentFrame(0);\n    const interval = setInterval(() => {\n      setCurrentFrame((prev) => (prev + 1) % 8);\n    }, 260);\n\n    return () => {\n      clearInterval(interval);\n    };\n  }, [isOpen]);\n\n  if (!isOpen) return null;\n\n  return (\n    <div\n      className=\"fixed inset-0 z-[2500] bg-black/90 backdrop-blur-md flex items-center justify-center p-3 sm:p-5 overflow-y-auto overscroll-contain touch-pan-y animate-fadeIn\"\n      role=\"dialog\"\n      aria-modal=\"true\"\n      aria-label=\"Investigação Inconclusiva\"\n      onTouchMove={(e) => {\n        if (e.target === e.currentTarget) {\n          e.preventDefault();\n        }\n      }}\n    >\n      <div className=\"w-full max-w-[560px] bg-[#0c0d10] border-2 border-[#2b2d36] rounded-[16px] shadow-[0_16px_60px_rgba(0,0,0,0.9)] overflow-hidden flex flex-col my-auto relative\">\n        \n        <div className=\"bg-[#07080a] border-b border-[#1f2128] p-[12px_18px] flex items-center justify-between gap-3\">\n          <div className=\"flex items-center gap-2\">\n            <AlertTriangle className=\"w-4 h-4 text-[#d94040]\" />\n            <span className=\"font-mono-retro text-[11px] sm:text-[12px] tracking-[0.16em] uppercase text-[#d94040] font-bold\">\n              CASO NÃO SOLUCIONADO · 1995\n            </span>\n          </div>\n\n          <span className=\"font-mono-retro text-[10px] tracking-[0.08em] text-[#9A9590] uppercase\">\n            RANCHO ESPERANÇA\n          </span>\n        </div>\n\n        <div className=\"p-4 sm:p-6 flex flex-col gap-4\">\n          \n          <div className=\"text-center flex flex-col items-center\">\n            <h2 className=\"font-brunson text-[30px] sm:text-[38px] uppercase tracking-[0.04em] leading-[0.95] text-[#F2EAE0] mb-2.5\">\n              Investigação<br />Inconclusiva\n            </h2>\n            <p className=\"font-mono-retro text-[12px] sm:text-[13px] text-[#b0a89c] leading-[1.7] italic max-w-[460px]\">\n              \"O caso permanece um mistério nas sombras. As evidências reunidas até o momento ainda deixam lacunas sobre o que realmente aconteceu no rancho. Seis vidas foram ceifadas, e a verdade continua oculta.\"\n            </p>\n          </div>\n\n          <div className=\"relative h-[250px] sm:h-[280px] w-full bg-[#000000] border border-[#20222a] rounded-[12px] flex items-center justify-center overflow-hidden\">\n\n            {Array.from({ length: 8 }, (_, i) => {\n              const isCurrent = i === currentFrame;\n              return (\n                <img\n                  key={i}\n                  src={`/assets/detetive_derrota/frame_${String(i).padStart(2, '0')}.png`}\n                  alt=\"Detetive desolado sob a luz da rua\"\n                  className={`absolute inset-0 m-auto h-[240px] sm:h-[270px] w-auto object-contain image-rendering-pixelated ${\n                    isCurrent ? 'opacity-100 z-10' : 'opacity-0 pointer-events-none z-0'\n                  }`}\n                  style={{ imageRendering: 'pixelated' }}\n                />\n              );\n            })}\n\n            <div className=\"absolute bottom-2.5 right-3 z-30 font-mono-retro text-[9px] uppercase tracking-[0.14em] text-[#9A9590] bg-[#0c0d10]/85 px-2 py-0.5 rounded border border-[#20222a]\">\n              DETETIVE · SEM CONCLUSÃO\n            </div>\n          </div>\n\n          <div className=\"flex flex-col gap-2.5 pt-1\">\n            <button\n              type=\"button\"\n              onClick={onReview}\n              className=\"w-full h-[48px] rounded-[10px] bg-[#7DD5D8] text-[#0D0D0D] font-mono-retro text-[12px] sm:text-[13px] font-bold uppercase tracking-[0.08em] cursor-pointer hover:bg-[#9DE0E3] transition-all flex items-center justify-center gap-2 shadow-[0_4px_14px_rgba(125,213,216,0.3)]\"\n            >\n              <FileText className=\"w-4 h-4 text-[#0D0D0D]\" />\n              <span>Ver Laudo e Corrigir Fichas</span>\n            </button>\n\n            <button\n              type=\"button\"\n              onClick={onRestart}\n              className=\"w-full h-[42px] rounded-[10px] bg-transparent border border-[#3e1a1a] text-[#d94040] font-mono-retro text-[11px] uppercase tracking-[0.08em] cursor-pointer hover:bg-[#220d0d] hover:border-[#602020] transition-all flex items-center justify-center gap-1.5\"\n            >\n              <RotateCcw className=\"w-3.5 h-3.5\" />\n              <span>Tentar Novamente do Zero</span>\n            </button>\n          </div>\n\n        </div>\n      </div>\n    </div>\n  );\n};\n",
  "src/components/RetroSheetModal.tsx": "import React from 'react';\nimport { useScrollLock } from '../hooks/useScrollLock';\n\ninterface RetroSheetModalProps {\n  isOpen: boolean;\n  onClose: () => void;\n}\n\nexport const RetroSheetModal: React.FC<RetroSheetModalProps> = ({ isOpen, onClose }) => {\n  useScrollLock(isOpen);\n\n  if (!isOpen) return null;\n\n  return (\n    <div\n      className=\"fixed inset-0 z-[700] bg-black/80 flex items-center justify-center p-2 sm:p-4 overscroll-contain touch-pan-y\"\n      onTouchMove={(e) => {\n        if (e.target === e.currentTarget) {\n          e.preventDefault();\n        }\n      }}\n    >\n      <div className=\"relative w-full max-w-5xl h-[90vh] bg-[#c0c0c0] border-2 border-t-white border-l-white border-r-black border-b-black shadow-2xl flex flex-col\">\n        <div className=\"bg-[#000080] text-white px-2 py-1 flex items-center justify-between font-mono-retro font-bold text-xs select-none\">\n          <div className=\"flex items-center gap-1\">\n            <span>📊</span>\n            <span>RetroSheet 95 — CONTROLE_DESPESAS_PRODUCAO.XLS</span>\n          </div>\n          <button\n            type=\"button\"\n            onClick={onClose}\n            className=\"w-5 h-5 bg-[#c0c0c0] text-black border border-t-white border-l-white border-r-black border-b-black flex items-center justify-center text-xs font-bold hover:bg-[#d4d0c8] active:border-t-black active:border-l-black active:border-r-white active:border-b-white leading-none\"\n          >\n            ✕\n          </button>\n        </div>\n\n        <div className=\"flex-1 w-full bg-[#008080] p-1 overflow-hidden\">\n          <iframe\n            src=\"/retrosheet-95.html\"\n            title=\"RetroSheet 95\"\n            className=\"w-full h-full border-none\"\n          />\n        </div>\n      </div>\n    </div>\n  );\n};\n"
};

for (const [relPath, content] of Object.entries(textFiles)) {
  const fullPath = path.resolve(relPath);
  fs.mkdirSync(path.dirname(fullPath), { recursive: true });
  fs.writeFileSync(fullPath, content, "utf8");
  console.log(" [OK] Atualizado:", relPath);
}

console.log("\n--> Executando build, git e deploy para Surge...");
try {
  execSync("npm run build", { stdio: "inherit" });
  execSync("git add .", { stdio: "inherit" });
  try {
    execSync('git commit -m "feat: inquerito 1995, boot retro, trava mobile e correcao completa de modais"', { stdio: "inherit" });
  } catch (e) {
    console.log("Sem novos commits pendentes.");
  }
  try {
    execSync("git push origin master", { stdio: "inherit" });
    console.log(" Push para o GitHub realizado!");
  } catch (err) {
    console.warn(" Aviso: Caso o Git recuse, use: git push origin master --force");
  }
  execSync("npx surge dist --domain https://identidade-oculta.surge.sh", { stdio: "inherit" });
  console.log("\n SUCESSO! Projeto compilado e publicado no Surge: https://identidade-oculta.surge.sh");
} catch (err) {
  console.error("\nErro durante o deploy:", err.message);
}